"""
Pre-translation cleanup for a DOCX source file.

Merges adjacent runs (w:r) that carry identical formatting. Word routinely
splits a single sentence across several runs; every split becomes a spurious
inline tag in the vendor's CAT tool, which hurts TM leverage and invites
tag-placement errors during translation.
"""
import shutil
import sys
import zipfile
from pathlib import Path

from lxml import etree

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
PARTS = ("word/document.xml", "word/footnotes.xml", "word/endnotes.xml", "word/header1.xml")


def _fingerprint(el):
    """Order-sensitive structural signature of an element subtree."""
    return (el.tag, tuple(sorted(el.attrib.items())), tuple(_fingerprint(c) for c in el))


def rpr_key(run):
    """Formatting fingerprint of a run: structure of its w:rPr, or '' if unformatted."""
    rpr = run.find(f"{{{W}}}rPr")
    return "" if rpr is None else repr(_fingerprint(rpr))


def is_text_only(run):
    """True if the run holds nothing but rPr and w:t (no breaks, tabs, drawings, footnote refs)."""
    allowed = {f"{{{W}}}rPr", f"{{{W}}}t"}
    return all(child.tag in allowed for child in run) and run.find(f"{{{W}}}t") is not None


def merge_runs(tree):
    merged = 0
    for para in tree.iter(f"{{{W}}}p"):
        prev = None
        for run in list(para):
            if run.tag != f"{{{W}}}r":
                prev = None  # a non-run sibling breaks adjacency
                continue
            if not is_text_only(run):
                prev = None
                continue
            if prev is not None and rpr_key(prev) == rpr_key(run):
                ptext = prev.find(f"{{{W}}}t")
                ptext.text = (ptext.text or "") + (run.find(f"{{{W}}}t").text or "")
                ptext.set("{http://www.w3.org/XML/1998/namespace}space", "preserve")
                para.remove(run)
                merged += 1
            else:
                prev = run
    return merged


def main(src, dst):
    shutil.copyfile(src, dst)
    zin = zipfile.ZipFile(src)
    items = {n: zin.read(n) for n in zin.namelist()}
    order = zin.namelist()
    zin.close()

    total = 0
    for part in PARTS:
        if part not in items:
            continue
        tree = etree.fromstring(items[part])
        n = merge_runs(tree)
        total += n
        if n:
            items[part] = etree.tostring(tree, xml_declaration=True, encoding="UTF-8", standalone=True)

    with zipfile.ZipFile(dst, "w", zipfile.ZIP_DEFLATED) as zout:
        for name in order:
            zout.writestr(name, items[name])
    print(f"merged {total} redundant run(s) -> {dst}")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

"""
Merge a translated XLIFF 1.2 file back into the prepared DOCX.

Rebuilds each translated paragraph's runs from the <target> content. Inline <g>
codes are resolved back to the run properties of the source run carrying the same
id, so bold/italic survive the round trip even if the translator moved the code.
Also retargets the document language so Word proofs the result in French.
"""
import json
import sys
import zipfile
from copy import deepcopy
from pathlib import Path

from lxml import etree

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XLF = "urn:oasis:names:tc:xliff:document:1.2"
XML = "http://www.w3.org/XML/1998/namespace"


def flatten(node):
    """Yield (rpr_id_or_None, text) pairs from XLIFF target content."""
    if node.text:
        yield None, node.text
    for child in node:
        tag = etree.QName(child).localname
        if tag == "g":
            yield child.get("id"), "".join(child.itertext())
        elif tag in ("mrk", "sub"):  # transparent wrappers: keep content, drop wrapper
            yield from flatten(child)
        elif tag in ("x", "bx", "ex", "ph", "bpt", "ept", "it"):
            pass  # standalone/paired placeholders carry no translatable text here
        if child.tail:
            yield None, child.tail


def make_run(rpr, text, lang):
    run = etree.Element(f"{{{W}}}r")
    props = deepcopy(rpr) if rpr is not None else etree.Element(f"{{{W}}}rPr")
    for existing in props.findall(f"{{{W}}}lang"):
        props.remove(existing)
    etree.SubElement(props, f"{{{W}}}lang").set(f"{{{W}}}val", lang)
    run.append(props)
    t = etree.SubElement(run, f"{{{W}}}t")
    t.text = text
    t.set(f"{{{XML}}}space", "preserve")
    return run


def retarget_language(items, lang):
    if "word/styles.xml" in items:
        styles = etree.fromstring(items["word/styles.xml"])
        for node in styles.iter(f"{{{W}}}lang"):
            node.set(f"{{{W}}}val", lang)
        items["word/styles.xml"] = etree.tostring(styles, xml_declaration=True, encoding="UTF-8", standalone=True)
    if "word/settings.xml" in items:
        settings = etree.fromstring(items["word/settings.xml"])
        for node in settings.iter(f"{{{W}}}themeFontLang"):
            node.set(f"{{{W}}}val", lang)
        items["word/settings.xml"] = etree.tostring(settings, xml_declaration=True, encoding="UTF-8", standalone=True)


def main(docx_path, xliff_path, skel_path, out_path, lang="fr-FR"):
    skel = json.loads(Path(skel_path).read_text())
    by_para = {u["para_index"]: u["unit"] for u in skel["units"]}

    xlf = etree.parse(xliff_path).getroot()
    targets, untranslated = {}, []
    for tu in xlf.iter(f"{{{XLF}}}trans-unit"):
        tgt = tu.find(f"{{{XLF}}}target")
        if tgt is None or not "".join(tgt.itertext()).strip():
            tgt = tu.find(f"{{{XLF}}}source")
            untranslated.append(tu.get("id"))
        targets[tu.get("id")] = tgt

    zin = zipfile.ZipFile(docx_path)
    order = zin.namelist()
    items = {n: zin.read(n) for n in order}
    zin.close()

    doc = etree.fromstring(items["word/document.xml"])
    rebuilt = 0
    for pidx, para in enumerate(doc.iter(f"{{{W}}}p")):
        unit = by_para.get(pidx)
        if unit is None or unit not in targets:
            continue
        rpr_by_id = {
            str(i): r.find(f"{{{W}}}rPr")
            for i, r in enumerate(para)
            if r.tag == f"{{{W}}}r"
        }
        for run in [c for c in para if c.tag == f"{{{W}}}r"]:
            para.remove(run)
        for rpr_id, text in flatten(targets[unit]):
            if not text:
                continue
            para.append(make_run(rpr_by_id.get(rpr_id), text, lang))
        rebuilt += 1

    items["word/document.xml"] = etree.tostring(doc, xml_declaration=True, encoding="UTF-8", standalone=True)
    retarget_language(items, lang)

    with zipfile.ZipFile(out_path, "w", zipfile.ZIP_DEFLATED) as zout:
        for name in order:
            zout.writestr(name, items[name])

    print(f"merged {rebuilt} paragraph(s) -> {out_path}")
    if untranslated:
        print(f"WARNING: {len(untranslated)} unit(s) had no target, source copied: {', '.join(untranslated)}")


if __name__ == "__main__":
    main(*sys.argv[1:])

