#!/usr/bin/env node
// Temporary shim: this kapi build (1.2.0-rc29) reads "kapi-bundle" (.kbf.json);
// @neokapi/i18n-react 1.2.3 emits the renamed "kapi-localization-format" (.klf).
// The payloads are byte-identical apart from the `kind` discriminator, so we
// just flip it. Delete this script once kapi reads .klf natively.
import { readdirSync, mkdirSync, readFileSync, writeFileSync, statSync } from "node:fs";
import { join, basename } from "node:path";

const [dir, outDir, direction] = process.argv.slice(2);
if (!dir || !outDir || !["to-kbf", "to-klf"].includes(direction)) {
  console.error("usage: klf-kbf.mjs <in-dir> <out-dir> <to-kbf|to-klf>");
  process.exit(2);
}
const from = direction === "to-kbf" ? ".klf" : ".kbf.json";
const to = direction === "to-kbf" ? ".kbf.json" : ".klf";
const kind = direction === "to-kbf" ? "kapi-bundle" : "kapi-localization-format";

const walk = (d) =>
  readdirSync(d).flatMap((e) => {
    const p = join(d, e);
    return statSync(p).isDirectory() ? walk(p) : p.endsWith(from) ? [p] : [];
  });

mkdirSync(outDir, { recursive: true });
let n = 0;
for (const file of walk(dir)) {
  const doc = JSON.parse(readFileSync(file, "utf8"));
  doc.kind = kind;
  writeFileSync(join(outDir, basename(file, from) + to), JSON.stringify(doc, null, 2));
  n++;
}
console.log(`${direction}: ${n} file(s) → ${outDir}`);

