import { useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { supportedLanguages } from './i18n';

const user = { name: 'Alex' };

export default function App() {
  const { t, i18n } = useTranslation();
  const count = 3;
  const language = i18n.resolvedLanguage;

  // Keep <html lang> in sync so screen readers, hyphenation and browser
  // translation follow the selected language.
  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  return (
    <main>
      <nav>
        <a href="/">{t('nav.dashboard')}</a>
        <a href="/tasks">{t('nav.tasks')}</a>
        <label>
          {t('language.label')}
          <select
            value={language}
            onChange={(event) => i18n.changeLanguage(event.target.value)}
          >
            {supportedLanguages.map(({ code, label }) => (
              <option key={code} value={code}>
                {label}
              </option>
            ))}
          </select>
        </label>
      </nav>
      <h1>{t('dashboard.greeting', { name: user.name })}</h1>
      <p>{t('dashboard.tasksDueToday', { count })}</p>
      <button>{t('dashboard.addTask')}</button>
      <label>
        <input type="checkbox" /> {t('dashboard.emailUpdates')}
      </label>
    </main>
