    fallbackLng: 'en',
    supportedLngs: supportedLanguages.map(({ code }) => code),
    load: 'languageOnly', // treat en-US, en-GB, ... as en
    interpolation: {
      escapeValue: false, // React escapes interpolated values already
    },
  });

export default i18n;

