    "@neokapi/i18n-react-lint": "^0.1.1",
    "oxlint": "^1.80.0"
  },
  "scripts": {
    "lint": "oxlint src/",
    "extract": "neokapi-i18n extract",
    "compile": "neokapi-i18n compile out/ --out public/translations",
    "i18n:gate": "npm run extract && node scripts/klf-kbf.mjs to-kbf i18n .kapi-bridge/in && kapi pseudo-translate .kapi-bridge/in --target-lang qps -o \".kapi-bridge/qps/{name}.{ext}\" && node scripts/klf-kbf.mjs to-klf .kapi-bridge/qps out && npm run compile",
    "i18n:translate": "node scripts/translate.mjs"
  }
}

#!/usr/bin/env node
/**
 * SHIM — delete once the toolchain agrees on one catalog format.
 *
 * @neokapi/i18n-react@1.2.3 writes catalogs with kind "kapi-localization-format"
 * (.klf); the kapi CLI (v1.2.0-rc29) reads kind "kapi-bundle" (.kbf.json).
 * The two schemas are otherwise byte-identical, so bridging is a rename of the
 * `kind` discriminator plus the file extension. Verified by round-tripping a
 * pseudo-translate: inline codes and {placeholders} survive intact.
 *
 *   node scripts/klf-kbf.mjs to-kbf <srcDir> <dstDir>
 *   node scripts/klf-kbf.mjs to-klf <srcDir> <dstDir>
 */
import { readdirSync, readFileSync, writeFileSync, mkdirSync, statSync } from "node:fs";
import { join, dirname, relative } from "node:path";

const [dir, src, dst] = process.argv.slice(2);
const MODES = {
  "to-kbf": { from: ".klf", to: ".kbf.json", kind: "kapi-bundle" },
  "to-klf": { from: ".kbf.json", to: ".klf", kind: "kapi-localization-format" },
};
const mode = MODES[dir];
if (!mode || !src || !dst) {
  console.error("usage: klf-kbf.mjs <to-kbf|to-klf> <srcDir> <dstDir>");
  process.exit(2);
}

const walk = (d) =>
  readdirSync(d).flatMap((e) => {
    const p = join(d, e);
    return statSync(p).isDirectory() ? walk(p) : p.endsWith(mode.from) ? [p] : [];
  });

const files = walk(src);
for (const file of files) {
  const doc = JSON.parse(readFileSync(file, "utf8"));
  doc.kind = mode.kind;
  const out = join(dst, relative(src, file).slice(0, -mode.from.length) + mode.to);
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, JSON.stringify(doc, null, 2) + "\n");
}
console.log(`${dir}: ${files.length} file(s) → ${dst}`);

#!/usr/bin/env node
/**
 * Translate the extracted catalog into one or more locales, routed through kapi
 * so terminology, placeholders and inline codes are enforced.
 *
 *   npm run i18n:translate -- fr de ja
 */
import { execFileSync } from "node:child_process";

const locales = process.argv.slice(2);
if (!locales.length) {
  console.error("usage: npm run i18n:translate -- <locale>...");
  process.exit(2);
}
const run = (cmd, args) => execFileSync(cmd, args, { stdio: "inherit" });

run("npm", ["run", "extract"]);
run("node", ["scripts/klf-kbf.mjs", "to-kbf", "i18n", ".kapi-bridge/in"]);
for (const lang of locales) {
  run("kapi", ["translate", ".kapi-bridge/in", "--target-lang", lang,
               "-o", `.kapi-bridge/${lang}/{name}.{ext}`]);
  run("node", ["scripts/klf-kbf.mjs", "to-klf", `.kapi-bridge/${lang}`, "out"]);
}
run("npm", ["run", "compile"]);

