  // Stand-in for the signed-in user; the name is data, never a translated string.
  const user = { name: 'Alex' };

  return (
    <I18nProvider catalogs={catalogs} locale={locale} fallbackLocale={DEFAULT_LOCALE}>
      <Dashboard user={user} />
