import { createContext, useContext, useEffect, useMemo } from 'react';
import { createTranslator, negotiateLocale, textDirection } from './translate.js';

const I18nContext = createContext(null);

function detectPreferredLocales() {
  if (typeof navigator === 'undefined') return [];
  return navigator.languages?.length ? [...navigator.languages] : [navigator.language];
}

/**
 * Provides the active locale and its translator to the tree.
 * Pass `locale` to force one; otherwise the browser's preference is negotiated
 * against the locales present in `catalogs`.
 */
export function I18nProvider({ catalogs, locale, fallbackLocale = 'en', children }) {
  const value = useMemo(() => {
    const available = Object.keys(catalogs);
    const active = negotiateLocale(
      locale ?? detectPreferredLocales(),
      available,
      fallbackLocale,
    );
    const t = createTranslator({
      locale: active,
      messages: catalogs[active],
      fallbackLocale,
      fallbackMessages: catalogs[fallbackLocale],
    });
    return { t, locale: active, dir: textDirection(active) };
  }, [catalogs, locale, fallbackLocale]);

  // Keeps screen readers, hyphenation and RTL mirroring in sync with the locale.
  useEffect(() => {
    if (typeof document === 'undefined') return;
    document.documentElement.lang = value.locale;
    document.documentElement.dir = value.dir;
  }, [value.locale, value.dir]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useTranslation() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useTranslation must be used inside <I18nProvider>');
  }
  return context;
}

/**
 * Framework-agnostic translation core.
 *
 * The `t(key, vars)` contract intentionally mirrors i18next:
 *   - `{{name}}` placeholders
 *   - plural forms as sibling keys `foo_one` / `foo_other` / `foo_few` / ...
 * so this module can be swapped for `react-i18next` without touching call sites.
 */

const RTL_LANGUAGES = new Set([
  'ar', 'ckb', 'dv', 'fa', 'he', 'ks', 'nqo', 'ps', 'sd', 'ug', 'ur', 'yi',
]);

const isProduction =
  typeof process !== 'undefined' && process.env?.NODE_ENV === 'production';

const warnedOnce = new Set();

function warn(message) {
  if (isProduction) return;
  if (warnedOnce.has(message)) return;
  warnedOnce.add(message);
  console.warn(`[i18n] ${message}`);
}

/** Collapse a nested catalog into dot-separated keys: {a:{b:'x'}} -> {'a.b':'x'} */
export function flattenCatalog(messages, prefix = '', out = {}) {
  for (const [name, value] of Object.entries(messages ?? {})) {
    const key = prefix ? `${prefix}.${name}` : name;
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      flattenCatalog(value, key, out);
    } else {
      out[key] = String(value);
    }
  }
  return out;
}

/** Resolve the writing direction for a locale, e.g. 'ar' -> 'rtl'. */
export function textDirection(locale) {
  try {
    const info = new Intl.Locale(locale);
    const direction = (
      typeof info.getTextInfo === 'function' ? info.getTextInfo() : info.textInfo
    )?.direction;
    if (direction) return direction;
  } catch {
    // Malformed tag - fall through to the language-subtag heuristic.
  }
  return RTL_LANGUAGES.has(String(locale).split('-')[0]) ? 'rtl' : 'ltr';
}

/**
 * Pick the best available locale for a user's preferences.
 * Tries exact match, then the bare language, then any regional variant of it.
 */
export function negotiateLocale(requested, available, fallbackLocale = 'en') {
  const wanted = (Array.isArray(requested) ? requested : [requested]).filter(Boolean);
  const offered = [...available];
  for (const tag of wanted) {
    if (offered.includes(tag)) return tag;
    const language = String(tag).split('-')[0];
    if (offered.includes(language)) return language;
    const regional = offered.find((candidate) => candidate.split('-')[0] === language);
    if (regional) return regional;
  }
  return fallbackLocale;
}

const PLACEHOLDER = /\{\{\s*([\w.]+)\s*\}\}/g;

function interpolate(template, vars, formatNumber, key) {
  if (!vars) return template;
  return template.replace(PLACEHOLDER, (placeholder, name) => {
    const value = vars[name];
    if (value === undefined || value === null) {
      warn(`missing value for "${name}" in "${key}"`);
      return placeholder;
    }
    return typeof value === 'number' ? formatNumber.format(value) : String(value);
  });
}

/**
 * Build a translator bound to one locale.
 * Falls back to `fallbackMessages` per key, so a partially translated catalog
 * degrades string-by-string rather than dropping the whole locale.
 */
export function createTranslator({
  locale,
  messages,
  fallbackLocale = 'en',
  fallbackMessages = null,
}) {
  const primary = flattenCatalog(messages);
  const fallback = fallbackMessages ? flattenCatalog(fallbackMessages) : null;
  const formatNumber = new Intl.NumberFormat(locale);

  // Each catalog is selected with its *own* language's plural rules: Polish
  // asks for `_few`, but the English fallback only ever has `_one` / `_other`.
  const pluralRules = new Intl.PluralRules(locale);
  const fallbackPluralRules = new Intl.PluralRules(fallbackLocale);

  function candidateKeys(key, count, rules) {
    if (count === undefined || count === null || !Number.isFinite(count)) return [key];
    return [`${key}_${rules.select(count)}`, `${key}_other`, key];
  }

  function lookup(key, count) {
    for (const candidate of candidateKeys(key, count, pluralRules)) {
      if (primary[candidate] !== undefined) return primary[candidate];
    }
    if (fallback) {
      for (const candidate of candidateKeys(key, count, fallbackPluralRules)) {
        if (fallback[candidate] !== undefined) {
          warn(`"${key}" is untranslated in "${locale}", using "${fallbackLocale}"`);
          return fallback[candidate];
        }
      }
    }
    warn(`no message for "${key}" in "${locale}"`);
    return key;
  }

  function t(key, vars) {
    return interpolate(lookup(key, vars?.count), vars, formatNumber, key);
  }

  t.locale = locale;
  return t;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import {
  createTranslator,
  flattenCatalog,
  negotiateLocale,
  textDirection,
} from './translate.js';
import { catalogs } from '../locales/index.js';

const en = catalogs.en;

// A deliberately Polish fixture: pl uses one/few/many/other, so it exercises
// plural handling that an `n === 1` check would silently get wrong.
const pl = {
  dashboard: {
    tasksDue_one: 'Masz {{count}} zadanie na dziś.',
    tasksDue_few: 'Masz {{count}} zadania na dziś.',
    tasksDue_many: 'Masz {{count}} zadań na dziś.',
    tasksDue_other: 'Masz {{count}} zadania na dziś.',
  },
};

function translator(locale, messages) {
  return createTranslator({
    locale,
    messages,
    fallbackLocale: 'en',
    fallbackMessages: en,
  });
}

test('selects English singular and plural forms', () => {
  const t = translator('en', en);
  assert.equal(t('dashboard.tasksDue', { count: 1 }), 'You have 1 task due today.');
  assert.equal(t('dashboard.tasksDue', { count: 3 }), 'You have 3 tasks due today.');
  assert.equal(t('dashboard.tasksDue', { count: 0 }), 'You have 0 tasks due today.');
});

test('selects the right Polish plural category for each count', () => {
  const t = translator('pl', pl);
  assert.equal(t('dashboard.tasksDue', { count: 1 }), 'Masz 1 zadanie na dziś.');
  assert.equal(t('dashboard.tasksDue', { count: 2 }), 'Masz 2 zadania na dziś.');
  assert.equal(t('dashboard.tasksDue', { count: 5 }), 'Masz 5 zadań na dziś.');
  assert.equal(t('dashboard.tasksDue', { count: 22 }), 'Masz 22 zadania na dziś.');
});

test('formats numbers using the active locale', () => {
  const t = translator('en', en);
  assert.equal(t('dashboard.tasksDue', { count: 1234 }), 'You have 1,234 tasks due today.');

  // Numbering system follows CLDR, not the language: ar-EG uses Arabic-Indic
  // digits while bare `ar` resolves to Latin ones.
  const egyptian = createTranslator({ locale: 'ar-EG', messages: {}, fallbackMessages: en });
  assert.match(egyptian('dashboard.tasksDue', { count: 3 }), /٣/);

  const plainArabic = createTranslator({ locale: 'ar', messages: {}, fallbackMessages: en });
  assert.match(plainArabic('dashboard.tasksDue', { count: 3 }), /3/);
});

test('interpolates named values without translating them', () => {
  const t = translator('en', en);
  assert.equal(t('dashboard.greeting', { name: 'Alex' }), 'Welcome back, Alex');
  assert.equal(t('dashboard.greeting', { name: '李雷' }), 'Welcome back, 李雷');
});

test('falls back per key, using the fallback locale plural rules', () => {
  // `pl` has no greeting, and its plural set does not match English's.
  const t = translator('pl', pl);
  assert.equal(t('dashboard.greeting', { name: 'Alex' }), 'Welcome back, Alex');
  assert.equal(t('nav.dashboard'), 'Dashboard');

  const sparse = translator('pl', {});
  assert.equal(sparse('dashboard.tasksDue', { count: 5 }), 'You have 5 tasks due today.');
  assert.equal(sparse('dashboard.tasksDue', { count: 1 }), 'You have 1 task due today.');
});

test('degrades visibly instead of throwing', () => {
  const t = translator('en', en);
  assert.equal(t('nav.nothingHere'), 'nav.nothingHere');
  assert.equal(t('dashboard.greeting', {}), 'Welcome back, {{name}}');
});

test('flattens nested catalogs into dot keys', () => {
  assert.deepEqual(flattenCatalog({ a: { b: 'x' }, c: 'y' }), { 'a.b': 'x', c: 'y' });
});

test('negotiates the closest available locale', () => {
  assert.equal(negotiateLocale(['pt-BR'], ['en', 'pt'], 'en'), 'pt');
  assert.equal(negotiateLocale(['fr'], ['en', 'fr-CA'], 'en'), 'fr-CA');
  assert.equal(negotiateLocale(['de', 'en'], ['en', 'pt'], 'en'), 'en');
  assert.equal(negotiateLocale([], ['en'], 'en'), 'en');
  assert.equal(negotiateLocale(['zz'], ['en'], 'en'), 'en');
});

test('resolves writing direction', () => {
  assert.equal(textDirection('en'), 'ltr');
  assert.equal(textDirection('ar'), 'rtl');
  assert.equal(textDirection('he-IL'), 'rtl');
  assert.equal(textDirection('not-a-locale!'), 'ltr');
});

test('every key used in the UI exists in the source catalog', () => {
  const appPath = fileURLToPath(new URL('../App.jsx', import.meta.url));
  const source = readFileSync(appPath, 'utf8');
  const used = [...source.matchAll(/\bt\(\s*'([^']+)'/g)].map((match) => match[1]);
  const flat = flattenCatalog(en);
  const categories = ['zero', 'one', 'two', 'few', 'many', 'other'];

  assert.ok(used.length > 0, 'expected App.jsx to call t()');
  for (const key of used) {
    const present =
      flat[key] !== undefined ||
      categories.some((category) => flat[`${key}_${category}`] !== undefined);
    assert.ok(present, `"${key}" is used in App.jsx but missing from en.json`);
  }
});

